pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(v[i] * 1000000000000000000 / 1000000000000000000 == v[i]);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = abi.decode(abi.encode(c.transfer(_tos, v)), (bool));
        bool allExtSucceed = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool s, bytes memory d) = c.caddress().call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), c.from(), _tos[i], v[i] * 1000000000000000000));
            if (!s) allExtSucceed = false;
        }
        if (allExtSucceed) {
            assertTrue(ok);
        }
    }
}
